97.sol:
"""Predict teen-number pairs and a separate 'life' vocabulary response.

A digit immediately following 1 activates strongly for 12--19, peaking near
15--18. These pairs count inside longer numbers too. Repeated 1 strengthens
the response; larger preceding digits weaken it. A decimal point, comma,
or space between the digits weakens it further. Fullwidth decimal digits
are treated like ordinary digits. Life-related words give a smaller positive
response, increased for several life-stage and social modifiers. Ordinal
suffixes and punctuation immediately after 1 receive negative predictions.
Only the previous two tokens are remembered, resetting at document changes.
"""
READS = ()

DIGIT_STRENGTH = (-0.06, 0.09, 0.76, 1.25, 1.47,
                  1.63, 1.65, 1.69, 1.61, 1.49)
LIFE_WORDS = {
    'life': 1.00, '-life': 0.83, 'lives': 0.54,
    'lifetime': 0.23, 'lifespan': 0.44, 'lifestyle': 0.30,
    'vida': 0.45, 'vie': 0.18, 'жизнь': 0.44, 'жизни': 0.44,
    '生命': 0.64, '命': 0.58, '生活': 0.50, '生活中': 0.70,
}
LIFE_STAGE_OR_SOCIAL = {
    'early', 'adult', 'american', 'christian', 'modern',
    'civilian', 'greek', 'family',
}
PERSONAL_OR_DAILY = {
    'personal', 'private', 'daily', 'everyday', 'political',
    'spiritual', 'school', 'later',
}


def digit(token):
    return int(token) if len(token) == 1 and token.isdecimal() else None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous, before = ('', '') if carry is None or carry[0] != doc else carry[1:]
    value = -0.001
    d, p, b = digit(token), digit(previous), digit(before)
    if d is not None:
        if p == 1:
            value = DIGIT_STRENGTH[d]
            if b == 1:
                value *= 1.14
            elif b is not None and b >= 2:
                value *= 1.0 - 0.02 * b
        elif b == 1 and previous in ('.', ',', ' '):
            value = DIGIT_STRENGTH[d] * {'.': 0.33, ',': 0.16, ' ': 0.20}[previous]
        elif p is not None and p >= 2 and d == 1:
            value = -0.08
    else:
        word, prior = token.strip().lower(), previous.strip().lower()
        value = LIFE_WORDS.get(word, value)
        if word in ('life', '-life'):
            if prior == 'real':
                value = 0.65
            elif prior in ('my', 'your', 'her', 'his', 'its'):
                value = 0.90
            elif prior in LIFE_STAGE_OR_SOCIAL:
                value = 1.55
            elif prior in PERSONAL_OR_DAILY:
                value = 1.28
        elif word == 'of' and prior in ('life', '-life'):
            value = 0.44
        if p == 1:
            if token in ('st', 'th'):
                value = -0.43 if token == 'st' else -0.22
            elif token in ('.', ','):
                value = -0.06
    return (doc, token, previous), float(value)

1678.sol:
"""Detect a digit following 1, with a response increasing strongly from 14 to 19.

ASCII and fullwidth digits are treated alike. The response is weaker inside
long digit strings, stronger after two 1s, and faint across number punctuation.
The same pattern occurs in Chinese-written year prefixes 一八 and 一九.
Other numeric positions receive small calibrated offsets; other text is zero.
"""
READS = ()
AFTER_ONE = (0.01, -0.08, -0.12, 0.11, 0.26,
             0.66, 0.90, 1.09, 1.29, 1.68)
START_DIGIT = (-0.005, 0.004, 0.001, -0.014, -0.039,
               0.016, 0.013, -0.002, -0.010, -0.026)
OTHER_DIGIT = (-0.006, 0.033, 0.003, -0.003, -0.057,
               0.003, -0.004, -0.017, -0.034, -0.021)


def digit(token):
    """Numerical value of a single ASCII or fullwidth digit, else None."""
    if len(token) == 1:
        if '0' <= token <= '9':
            return ord(token) - ord('0')
        if '０' <= token <= '９':
            return ord(token) - ord('０')
    return None


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous, before = '', ''
    if carry and carry[0] == document:
        previous, before = carry[1:]
    current, preceding, earlier = digit(token), digit(previous), digit(before)
    value = 0.0
    if current is not None:
        value = START_DIGIT[current] if preceding is None else OTHER_DIGIT[current]
        if preceding == 1:
            value = AFTER_ONE[current]
            if current >= 4:
                if earlier == 1:
                    value += 0.13
                elif earlier is not None:
                    value *= 0.90 if current == 9 else 0.94
        elif earlier == 1 and previous in ('.', ',', '/', '-', ':'):
            strength = 0.25 if previous == '.' else 0.10
            value += strength * max(0.0, AFTER_ONE[current])
    elif previous.endswith('一'):
        if token == '八':
            value = 0.53
        elif token == '九':
            value = 1.08
        elif token == '九年':
            value = 0.51
    return (document, token, previous), float(value)

2431.sol:
"""A short-range numeral-pattern response, otherwise close to zero.

The strongest negative response is the second digit of 11--19 or 20,
including such pairs inside longer numbers. Separators weaken this effect.
Five is positive away from these pairs. Written teen numbers have a smaller
negative response too. Decimal digit glyphs use the same digit rules.
English number words and several Chinese numeral forms are also handled.
Only two previous tokens are kept, resetting at document boundaries.
"""
import unicodedata

READS = ()
AFTER_ONE = (0.05, -0.69, -1.78, -2.90, -3.36,
             -3.22, -3.73, -3.90, -3.83, -3.65)
BASE_DIGIT = (0.02, -0.02, 0.01, -0.03, -0.02,
              0.43, 0.01, 0.02, 0.02, -0.01)
SEPARATORS = {'.': 0.31, ' ': 0.22, ':': 0.12,
              ',': 0.18, '-': 0.07, '/': 0.06}
TEENS = set('thirteen fourteen sixteen seventeen eighteen nineteen'.split())
ORDINAL_TEENS = set(('eleventh twelfth thirteenth fourteenth fifteenth '
                     'sixteenth seventeenth eighteenth nineteenth').split())
NUMBER_WORDS = {
    'eleven': -0.77, 'twelve': -0.89, 'fifteen': -0.97,
    'five': 0.59, 'fifth': 0.36, 'fifty': 0.39,
    'three': 0.06, 'four': 0.09, 'twenty': -0.20,
    'twentieth': -0.74, 'hundred': -0.15,
}
CJK_DIGITS = '零一二三四五六七八九'


def decimal_token(s):
    if len(s) == 1 and s.isdecimal():
        return str(unicodedata.decimal(s))
    return s


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before = '', ''
    else:
        _, previous, before = carry
    raw = prefix.token_strings[-1]
    token = decimal_token(raw)
    value = 0.0
    if len(token) == 1 and token in '0123456789':
        digit = int(token)
        value = BASE_DIGIT[digit]
        if previous == '1':
            value = AFTER_ONE[digit]
            if digit >= 2:
                if before == '1':
                    value *= 1.15
                elif before == '0':
                    value *= 1.03
                elif before and before in '23456789':
                    value *= 0.92
        elif previous == '2' and token == '0':
            value = -1.68
        elif previous == '2' and token == '1':
            value = -0.32
        elif previous == '3' and token == '0':
            value = -0.26
        elif before == '1' and previous in SEPARATORS:
            value += SEPARATORS[previous] * (
                AFTER_ONE[digit] - BASE_DIGIT[digit])
        elif token == '5':
            if previous in (' ', '0'):
                value = 0.55
            elif previous and previous in '23679':
                value = 0.31
        elif previous == ' ' and digit >= 3:
            value += 0.06
        elif previous and previous in '679' and digit >= 3:
            value -= 0.08
    elif token == '.' and previous == '1':
        value = 0.23
    else:
        word = token.strip().lower()
        if word in NUMBER_WORDS:
            value = NUMBER_WORDS[word]
        elif word in TEENS:
            value = -1.20
        elif word in ORDINAL_TEENS:
            value = -1.07
        elif token in ('teen', 'teenth', 'eenth', 'irteen'):
            value = -1.10
        elif word in ('third', 'fourth', 'sixth', 'seventh',
                      'eighth', 'ninth', 'tenth'):
            value = -0.16
        elif token in ('²', '³'):
            value = -0.09 if token == '²' else -0.13
        elif len(word) >= 2 and word[0] == '十' and word[1] in CJK_DIGITS[1:]:
            digit = CJK_DIGITS.index(word[1])
            value = -1.0 if digit == 1 else -1.2 if digit == 2 else -1.5
        elif word and word[0] in CJK_DIGITS and word[1:] in ('', '年', '月', '日'):
            digit = CJK_DIGITS.index(word[0])
            if previous.endswith('一') and digit >= 2:
                value = 0.5 * AFTER_ONE[digit]
            elif digit == 5:
                value = 0.65
    return (doc, token, previous), float(value)

5802.sol:
"""Approximate local digit, ordering and quantity token-pair responses.

The strongest mode is a digit immediately following 1, even inside longer
numbers. Its response is largest for 0, 1 and 2, declining toward 9.
Other modes are negative responses in phrases like 'first time' or 'next
step', and positive responses in 'first few', 'each of' and 'any of'.
Small offsets cover other digits and non-digits after 1. Only the previous
token is retained; document boundaries clear that context. These rules do
not represent the component's finer lexical or longer-context variation.
"""
READS = ()

# These profiles are indexed by decimal digit value, not tokenizer ids.
AFTER_ONE = (
    1.60, 1.42, 1.42, 1.17, 0.93, 0.66, 0.33, 0.19, 0.0, -0.14,
)
OTHER_DIGITS = (
    0.0, 0.0, 0.01, -0.01, -0.01, -0.01, -0.067, -0.05, -0.016, 0.077,
)
TIME_ORDER = {
    'first': -2.55, 'second': -1.90, 'third': -2.0,
    'next': -2.95, 'last': -2.15,
    'every': -1.48, 'each': -1.32, 'any': -0.80, 'one': -0.98,
}
# Other ordering nouns receive a smaller version of the time response.
ORDER_NOUNS = {
    'place': 0.61, 'step': 0.45, 'day': 0.44, 'year': 0.38,
    'week': 0.28, 'night': 0.27, 'minute': 0.35,
    'generation': 0.40, 'thing': 0.52,
}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    value = -0.063 if previous == '1' else 0.0
    if len(token) == 1 and token in '0123456789':
        responses = AFTER_ONE if previous == '1' else OTHER_DIGITS
        value = responses[int(token)]
    else:
        before = previous.strip().lower()
        word = token.strip().lower().lstrip('-')
        if word == 'time':
            value = TIME_ORDER.get(before, 0.0)
        elif before in {'first', 'second', 'third', 'next', 'last'}:
            if word == 'few':
                value = 1.55 if before == 'first' else 1.15
            else:
                value = TIME_ORDER[before] * ORDER_NOUNS.get(word, 0.0)
        elif word == 'of':
            value = {'each': 0.96, 'any': 0.61}.get(before, 0.0)
    return (document, token), float(value)

5882.sol:
"""A signal for digit continuations after '1', and for movement/proximity words.

The digit response grows roughly logarithmically with its numeric value
when it follows token '1' (more weakly across a decimal point). Direction
toward something and comparative nearness give negative responses. 'After' continuations, especially 'after all', give
positive responses. A few 'other/another' phrases are positive as well.
Unmatched tokens receive zero; small token-specific effects are omitted.
"""
from math import log

READS = ()

NEARNESS = {
    'toward': -3.88,
    'towards': -3.83,
    'closer': -2.28,
    'closest': -1.24,
    'nearest': -1.41,
    'near': -0.57,
    'tow': -2.28,  # The 'Tow' fragment also occurs in towels.
}


PROXIMITY_TO = {
    'close': -0.75, 'closer': -2.16,
    'closest': -1.59, 'nearest': -1.07,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is not None and carry[0] == doc:
        previous, penultimate = carry[1:]
    else:
        previous = penultimate = ''
    value = 0.0
    if len(token) == 1 and token in '0123456789':
        digit = int(token)
        strength = -0.05 if digit < 2 else 0.80 * log(digit) - 0.39
        if previous == '1':
            value = strength
        elif penultimate == '1' and previous == '.':
            value = 0.28 * strength
    else:
        word = token.strip().lower()
        before = previous.strip().lower()
        value = NEARNESS.get(word, 0.0)
        if before in {'t', 'tow'}:
            value = NEARNESS.get(before + word, value)
        if before == 'after':
            if word == 'all':
                value = 4.23
            elif word == 'being':
                value = 2.27
            elif word in {'the', 'a', 'an', 'his', 'her', 'this', 'its'}:
                value = 0.20
            elif word in {'each', 'every', 'some', 'several', 'much',
                          'both', 'any', 'many'}:
                value = 1.24
            elif word.isalpha():
                value = 0.26 if word.endswith('ing') else 0.41
        elif word == 'to' and before in PROXIMITY_TO:
            value = PROXIMITY_TO[before]
        elif word == 'the' and before in {'toward', 'towards', 'near'}:
            value = -0.80
        elif before in {'other', 'another'}:
            if word == 'hand':
                value = 0.84
            elif word == 'way':
                value = 0.60
            elif word == 'half':
                value = 1.06
    return (doc, token, previous), float(value)
